-- 迁移 095：财务到款池、可配置费用提取、到款认领/批量分配和经费卡拆分。
-- 本迁移只记录科研系统业务事实；不会伪造财务系统凭证、付款回执或外部卡号。
BEGIN;

CREATE TABLE IF NOT EXISTS "到账费用提取方案" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "方案名称" varchar(200) NOT NULL,
    "版本号" integer NOT NULL DEFAULT 1,
    "业务类型" varchar(50) NOT NULL DEFAULT '科研经费到账',
    "状态" varchar(20) NOT NULL DEFAULT '草稿',
    "生效日期" date,
    "失效日期" date,
    "说明" varchar(1000),
    "创建人编号" integer NOT NULL,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_到账费用提取方案" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_到账费用提取方案_版本" UNIQUE ("业务类型", "版本号"),
    CONSTRAINT "ck_到账费用提取方案_状态" CHECK ("状态" IN ('草稿','生效','停用')),
    CONSTRAINT "ck_到账费用提取方案_日期" CHECK ("失效日期" IS NULL OR "生效日期" IS NULL OR "失效日期" >= "生效日期")
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_到账费用提取方案_生效" ON "到账费用提取方案" ("业务类型") WHERE "状态" = '生效';

CREATE TABLE IF NOT EXISTS "到账费用提取规则" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "方案编号" bigint NOT NULL,
    "序号" integer NOT NULL,
    "费用类型" varchar(100) NOT NULL,
    "计算方式" varchar(20) NOT NULL DEFAULT '比例',
    "计算值" numeric(18,8) NOT NULL DEFAULT 0,
    "上限金额" numeric(18,2),
    "是否启用" boolean NOT NULL DEFAULT true,
    "说明" varchar(500),
    CONSTRAINT "pk_到账费用提取规则" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_到账费用提取规则_顺序" UNIQUE ("方案编号", "序号"),
    CONSTRAINT "fk_到账费用提取规则_方案" FOREIGN KEY ("方案编号") REFERENCES "到账费用提取方案" ("编号") ON DELETE CASCADE,
    CONSTRAINT "ck_到账费用提取规则_方式" CHECK ("计算方式" IN ('比例','固定金额')),
    CONSTRAINT "ck_到账费用提取规则_值" CHECK ("计算值" >= 0 AND ("上限金额" IS NULL OR "上限金额" >= 0))
);
CREATE INDEX IF NOT EXISTS "ix_到账费用提取规则_方案" ON "到账费用提取规则" ("方案编号", "序号");

CREATE TABLE IF NOT EXISTS "财务到款登记" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "外部系统编号" bigint,
    "外部单据号" varchar(100) NOT NULL,
    "同步批次号" varchar(100),
    "到款日期" date NOT NULL,
    "到款金额" numeric(18,2) NOT NULL,
    "到款单位" varchar(200) NOT NULL,
    "摘要" varchar(1000),
    "凭证路径" text,
    "来源" varchar(30) NOT NULL DEFAULT '财务适配器',
    "状态" varchar(30) NOT NULL DEFAULT '待财务核验',
    "核验人编号" integer,
    "核验时间" timestamp without time zone,
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_财务到款登记" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_财务到款登记_外部单据" UNIQUE ("外部系统编号", "外部单据号"),
    CONSTRAINT "ck_财务到款登记_金额" CHECK ("到款金额" > 0),
    CONSTRAINT "ck_财务到款登记_来源" CHECK ("来源" IN ('财务适配器','人工登记')),
    CONSTRAINT "ck_财务到款登记_状态" CHECK ("状态" IN ('待财务核验','待认领','部分认领','已认领','已冲销'))
);
CREATE INDEX IF NOT EXISTS "ix_财务到款登记_状态日期" ON "财务到款登记" ("状态", "到款日期" DESC);

CREATE TABLE IF NOT EXISTS "财务到款认领" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "到款登记编号" bigint NOT NULL,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "认领金额" numeric(18,2) NOT NULL,
    "提取方案编号" bigint,
    "费用明细" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "认领说明" varchar(1000),
    "状态" varchar(20) NOT NULL DEFAULT '已认领',
    "认领人编号" integer NOT NULL,
    "认领时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "作废人编号" integer,
    "作废时间" timestamp without time zone,
    CONSTRAINT "pk_财务到款认领" PRIMARY KEY ("编号"),
    CONSTRAINT "fk_财务到款认领_到款" FOREIGN KEY ("到款登记编号") REFERENCES "财务到款登记" ("编号"),
    CONSTRAINT "fk_财务到款认领_方案" FOREIGN KEY ("提取方案编号") REFERENCES "到账费用提取方案" ("编号"),
    CONSTRAINT "ck_财务到款认领_金额" CHECK ("认领金额" > 0),
    CONSTRAINT "ck_财务到款认领_状态" CHECK ("状态" IN ('已认领','已作废'))
);
CREATE INDEX IF NOT EXISTS "ix_财务到款认领_项目" ON "财务到款认领" ("流程模板编号", "项目编号", "认领时间" DESC);

CREATE TABLE IF NOT EXISTS "项目经费卡" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "父卡编号" bigint,
    "来源认领编号" bigint,
    "内部卡号" varchar(100) NOT NULL,
    "财务卡号" varchar(100),
    "卡片名称" varchar(200) NOT NULL,
    "分配金额" numeric(18,2) NOT NULL DEFAULT 0,
    "已使用金额" numeric(18,2) NOT NULL DEFAULT 0,
    "状态" varchar(30) NOT NULL DEFAULT '待财务建卡',
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_项目经费卡" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_项目经费卡_内部卡号" UNIQUE ("内部卡号"),
    CONSTRAINT "fk_项目经费卡_父卡" FOREIGN KEY ("父卡编号") REFERENCES "项目经费卡" ("编号"),
    CONSTRAINT "fk_项目经费卡_认领" FOREIGN KEY ("来源认领编号") REFERENCES "财务到款认领" ("编号"),
    CONSTRAINT "ck_项目经费卡_金额" CHECK ("分配金额" >= 0 AND "已使用金额" >= 0 AND "已使用金额" <= "分配金额"),
    CONSTRAINT "ck_项目经费卡_状态" CHECK ("状态" IN ('待财务建卡','有效','已拆分','已关闭'))
);
CREATE INDEX IF NOT EXISTS "ix_项目经费卡_项目" ON "项目经费卡" ("流程模板编号", "项目编号", "状态");

CREATE TABLE IF NOT EXISTS "财务到款操作审计" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "到款登记编号" bigint,
    "认领编号" bigint,
    "操作类型" varchar(50) NOT NULL,
    "操作人编号" integer NOT NULL,
    "说明" varchar(2000),
    "请求编号" varchar(64),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_财务到款操作审计" PRIMARY KEY ("编号")
);
CREATE INDEX IF NOT EXISTS "ix_财务到款操作审计_到款时间" ON "财务到款操作审计" ("到款登记编号", "创建时间" DESC);

CREATE OR REPLACE FUNCTION "tfn_到账费用提取预览"(p_scheme_id bigint, p_amount numeric)
RETURNS TABLE ("费用类型" varchar, "计算方式" varchar, "提取金额" numeric, "规则编号" bigint)
LANGUAGE sql STABLE AS $$
    SELECT r."费用类型", r."计算方式",
           ROUND(LEAST(CASE WHEN r."计算方式"='比例' THEN p_amount * r."计算值" / 100 ELSE r."计算值" END,
                       COALESCE(r."上限金额", 999999999999.99)), 2) AS "提取金额",
           r."编号"
      FROM "到账费用提取规则" r
     WHERE r."方案编号" = p_scheme_id AND r."是否启用" = TRUE
     ORDER BY r."序号";
$$;

CREATE OR REPLACE FUNCTION "fn_到账费用提取明细"(p_scheme_id bigint, p_amount numeric)
RETURNS jsonb LANGUAGE sql STABLE AS $$
    SELECT COALESCE(jsonb_agg(jsonb_build_object('费用类型', "费用类型", '计算方式', "计算方式", '提取金额', "提取金额", '规则编号', "规则编号") ORDER BY "规则编号"), '[]'::jsonb)
      FROM "tfn_到账费用提取预览"(p_scheme_id, p_amount);
$$;

CREATE OR REPLACE FUNCTION "sp_财务到款登记"(p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE v_id bigint;
BEGIN
    IF COALESCE(NULLIF(p_payload->>'外部单据号',''),'') = '' OR COALESCE(NULLIF(p_payload->>'到款单位',''),'') = '' THEN
        RAISE EXCEPTION '外部单据号和到款单位不能为空' USING ERRCODE='22023';
    END IF;
    IF COALESCE((p_payload->>'到款金额')::numeric,0) <= 0 THEN
        RAISE EXCEPTION '到款金额必须大于 0' USING ERRCODE='22023';
    END IF;
    IF COALESCE(NULLIF(p_payload->>'来源',''),'财务适配器') = '财务适配器'
       AND COALESCE(NULLIF(p_payload->>'外部系统编号',''),'') = '' THEN
        RAISE EXCEPTION '财务适配器来源必须提供外部系统编号' USING ERRCODE='22023';
    END IF;
    IF NULLIF(p_payload->>'外部系统编号','') IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM "外部系统" WHERE "编号"=(p_payload->>'外部系统编号')::bigint AND "系统类型"='财务') THEN
        RAISE EXCEPTION '外部系统不存在或不是财务类型' USING ERRCODE='22023';
    END IF;
    INSERT INTO "财务到款登记" ("外部系统编号","外部单据号","同步批次号","到款日期","到款金额","到款单位","摘要","凭证路径","来源","状态","建立人编号")
    VALUES (NULLIF(p_payload->>'外部系统编号','')::bigint, trim(p_payload->>'外部单据号'), NULLIF(p_payload->>'同步批次号',''),
            COALESCE(NULLIF(p_payload->>'到款日期','')::date,CURRENT_DATE), (p_payload->>'到款金额')::numeric,
            trim(p_payload->>'到款单位'), NULLIF(p_payload->>'摘要',''), NULLIF(p_payload->>'凭证路径',''),
            COALESCE(NULLIF(p_payload->>'来源',''),'财务适配器'), '待财务核验', (p_payload->>'建立人编号')::integer)
    ON CONFLICT ("外部系统编号","外部单据号") DO UPDATE SET
       "同步批次号"=EXCLUDED."同步批次号", "到款日期"=EXCLUDED."到款日期", "到款金额"=EXCLUDED."到款金额",
       "到款单位"=EXCLUDED."到款单位", "摘要"=EXCLUDED."摘要", "凭证路径"=EXCLUDED."凭证路径", "更新时间"=CURRENT_TIMESTAMP
    RETURNING "编号" INTO v_id;
    INSERT INTO "财务到款操作审计" ("到款登记编号","操作类型","操作人编号","说明")
    VALUES (v_id,'登记到款',(p_payload->>'建立人编号')::integer,'记录财务到款事实，等待财务核验，未生成外部回执');
    RETURN jsonb_build_object('编号',v_id,'状态','待财务核验','真实财务回执',false);
END; $$;

CREATE OR REPLACE FUNCTION "sp_财务到款确认"(p_id bigint, p_operator_id integer)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE v_status varchar(30);
BEGIN
    SELECT "状态" INTO v_status FROM "财务到款登记" WHERE "编号"=p_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '到款登记不存在' USING ERRCODE='P0002'; END IF;
    IF v_status = '已冲销' THEN RAISE EXCEPTION '已冲销到款不能确认' USING ERRCODE='22023'; END IF;
    UPDATE "财务到款登记" SET "状态"='待认领',"核验人编号"=p_operator_id,"核验时间"=CURRENT_TIMESTAMP,"更新时间"=CURRENT_TIMESTAMP WHERE "编号"=p_id;
    INSERT INTO "财务到款操作审计" ("到款登记编号","操作类型","操作人编号","说明") VALUES (p_id,'财务核验',(p_operator_id),'仅确认本系统登记事实，外部财务凭证仍以财务系统为准');
    RETURN jsonb_build_object('编号',p_id,'状态','待认领','真实财务回执',false);
END; $$;

CREATE OR REPLACE FUNCTION "sp_财务到款认领"(p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE v_incoming record; v_claim_id bigint; v_available numeric; v_scheme_id bigint; v_amount numeric; v_flow integer; v_project integer; v_card_id bigint;
BEGIN
    v_amount := (p_payload->>'认领金额')::numeric; v_flow := (p_payload->>'流程模板编号')::integer; v_project := (p_payload->>'项目编号')::integer; v_scheme_id := NULLIF(p_payload->>'提取方案编号','')::bigint;
    IF v_amount IS NULL OR v_amount <= 0 OR v_flow IS NULL OR v_project IS NULL THEN RAISE EXCEPTION '到款认领项目、流程和金额不能为空' USING ERRCODE='22023'; END IF;
    SELECT * INTO v_incoming FROM "财务到款登记" WHERE "编号"=(p_payload->>'到款登记编号')::bigint FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '到款登记不存在' USING ERRCODE='P0002'; END IF;
    IF v_incoming."状态" NOT IN ('待认领','部分认领') THEN RAISE EXCEPTION '到款状态为 %，不可认领',v_incoming."状态" USING ERRCODE='22023'; END IF;
    SELECT v_incoming."到款金额" - COALESCE(SUM("认领金额") FILTER (WHERE "状态"='已认领'),0) INTO v_available FROM "财务到款认领" WHERE "到款登记编号"=v_incoming."编号";
    IF v_amount > v_available THEN RAISE EXCEPTION '认领金额超过可分配余额（可分配：%）',v_available USING ERRCODE='22023'; END IF;
    IF NOT EXISTS (SELECT 1 FROM "纵向项目立项" WHERE "编号"=v_project) AND NOT EXISTS (SELECT 1 FROM "横向项目" WHERE "编号"=v_project) THEN RAISE EXCEPTION '项目不存在，拒绝认领' USING ERRCODE='P0002'; END IF;
    IF v_scheme_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "到账费用提取方案" WHERE "编号"=v_scheme_id AND "状态"='生效') THEN RAISE EXCEPTION '费用提取方案不存在或未生效' USING ERRCODE='22023'; END IF;
    INSERT INTO "财务到款认领" ("到款登记编号","流程模板编号","项目编号","认领金额","提取方案编号","费用明细","认领说明","认领人编号")
    VALUES (v_incoming."编号",v_flow,v_project,v_amount,v_scheme_id,COALESCE("fn_到账费用提取明细"(v_scheme_id,v_amount),'[]'::jsonb),NULLIF(p_payload->>'认领说明',''),(p_payload->>'认领人编号')::integer)
    RETURNING "编号" INTO v_claim_id;
    INSERT INTO "项目经费卡" ("流程模板编号","项目编号","来源认领编号","内部卡号","卡片名称","分配金额","建立人编号")
    VALUES (v_flow,v_project,v_claim_id,'SR-CARD-'||v_claim_id,'到账认领经费卡-'||v_claim_id,v_amount,(p_payload->>'认领人编号')::integer)
    RETURNING "编号" INTO v_card_id;
    UPDATE "财务到款登记" SET "状态"=CASE WHEN v_amount = v_available THEN '已认领' ELSE '部分认领' END,"更新时间"=CURRENT_TIMESTAMP WHERE "编号"=v_incoming."编号";
    INSERT INTO "财务到款操作审计" ("到款登记编号","认领编号","操作类型","操作人编号","说明") VALUES (v_incoming."编号",v_claim_id,'到款认领',(p_payload->>'认领人编号')::integer,'认领已写入科研系统并生成待财务建卡的内部卡；未伪造外部卡号');
    RETURN jsonb_build_object('认领编号',v_claim_id,'经费卡编号',v_card_id,'认领金额',v_amount,'剩余可认领',v_available-v_amount,'真实财务回执',false);
END; $$;

CREATE OR REPLACE FUNCTION "sp_财务到款批量认领"(p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE v_item jsonb; v_result jsonb := '[]'::jsonb; v_row jsonb;
BEGIN
    IF jsonb_typeof(p_payload->'分配列表') <> 'array' OR jsonb_array_length(p_payload->'分配列表') = 0 THEN RAISE EXCEPTION '分配列表不能为空' USING ERRCODE='22023'; END IF;
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_payload->'分配列表') LOOP
        v_row := "sp_财务到款认领"(jsonb_build_object('到款登记编号',p_payload->>'到款登记编号','认领人编号',p_payload->>'认领人编号') || v_item);
        v_result := v_result || jsonb_build_array(v_row);
    END LOOP;
    RETURN jsonb_build_object('结果',v_result,'数量',jsonb_array_length(v_result),'真实财务回执',false);
END; $$;

CREATE OR REPLACE FUNCTION "sp_项目经费卡拆分"(p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE v_parent record; v_amount numeric; v_child bigint; v_operator integer;
BEGIN
    v_amount := (p_payload->>'拆分金额')::numeric; v_operator := (p_payload->>'操作人编号')::integer;
    SELECT * INTO v_parent FROM "项目经费卡" WHERE "编号"=(p_payload->>'父卡编号')::bigint FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '父经费卡不存在' USING ERRCODE='P0002'; END IF;
    IF v_amount IS NULL OR v_amount <= 0 OR v_amount > v_parent."分配金额"-v_parent."已使用金额" THEN RAISE EXCEPTION '拆分金额超过父卡可用余额' USING ERRCODE='22023'; END IF;
    INSERT INTO "项目经费卡" ("流程模板编号","项目编号","父卡编号","来源认领编号","内部卡号","卡片名称","分配金额","状态","建立人编号")
    VALUES (v_parent."流程模板编号",v_parent."项目编号",v_parent."编号",v_parent."来源认领编号",'SR-CARD-SPLIT-'||nextval('"项目经费卡_编号_seq"'),'拆分经费卡-'||v_parent."编号",v_amount,'待财务建卡',v_operator)
    RETURNING "编号" INTO v_child;
    UPDATE "项目经费卡" SET "状态"='已拆分',"更新时间"=CURRENT_TIMESTAMP WHERE "编号"=v_parent."编号";
    INSERT INTO "财务到款操作审计" ("认领编号","操作类型","操作人编号","说明") VALUES (v_parent."来源认领编号",'经费卡拆分',v_operator,'仅拆分科研系统内部卡额度，外部财务卡号需由财务系统返回');
    RETURN jsonb_build_object('父卡编号',v_parent."编号",'子卡编号',v_child,'拆分金额',v_amount,'真实财务回执',false);
END; $$;

UPDATE "系统迁移版本"
   SET "版本"=95,"脚本"='095_finance_incoming_claim_and_card.sql',
       "检查摘要"='财务到款池、可配置费用提取、到款认领批量分配和经费卡拆分，未伪造财务回执',"应用时间"=CURRENT_TIMESTAMP
 WHERE "编号"=1;

COMMIT;
